<script setup lang="ts">
// Browsable parts catalogue (docs/catalog/parts.json, generated by `make catalog`).
import { computed, onMounted, ref } from 'vue';
import { withBase } from 'vitepress';
import { dataUrl, defineMessages, formatMoney, useLocale, useLocalePath } from '../i18n';

const useMessages = defineMessages({
  en: {
    loadError: (error: string) => `The parts catalogue could not be loaded (${error}). The`, pdf: 'catalogue PDF', samePdf: 'has the same content.',
    all: 'All parts', printed: 'Printed', purchased: 'Purchased', fastener: 'Fasteners', filter: 'Filter by name…', filterLabel: 'Filter parts',
    size: 'Size', mass: 'Mass', each: 'g each', filament: 'Filament', supports: ', supports', file: 'File', buy: 'Buy', steps: 'Steps',
    colour: (colour: string) => colour,
  },
  de: {
    loadError: (error: string) => `Der Teilekatalog konnte nicht geladen werden (${error}). Das`, pdf: 'Katalog-PDF', samePdf: 'enthält dieselben Angaben.',
    all: 'Alle Teile', printed: 'Gedruckt', purchased: 'Gekauft', fastener: 'Verbindungselemente', filter: 'Nach Name filtern…', filterLabel: 'Teile filtern',
    size: 'Größe', mass: 'Masse', each: 'g je Stück', filament: 'Filament', supports: ', mit Stützen', file: 'Datei', buy: 'Kaufen', steps: 'Schritte',
    colour: (colour: string) => (colour.startsWith('secondary') ? 'sekundär (Limette)' : 'primär (Graphit)'),
  },
});
const t = useMessages();
const locale = useLocale();
const localePath = useLocalePath();

interface Part {
  id: string; kind: 'printed' | 'purchased' | 'fastener'; title: string; qty: number; bbox_mm?: number[];
  mass_g?: number; image?: string; colour?: string; file?: string; supports?: boolean; source?: string;
  vendor?: string; sku?: string; price_eur?: number; pack?: number; steps?: number[]; note?: string;
}

const parts = ref<Part[]>([]);
const error = ref('');
const kind = ref<'all' | Part['kind']>('all');
const query = ref('');
const shown = computed(() => parts.value.filter((part) => (kind.value === 'all' || part.kind === kind.value)
  && (!query.value || `${part.id} ${part.title}`.toLowerCase().includes(query.value.toLowerCase()))));
const totals = computed(() => ({
  printed: parts.value.filter((p) => p.kind === 'printed').reduce((sum, p) => sum + p.qty, 0),
  purchased: parts.value.filter((p) => p.kind === 'purchased').reduce((sum, p) => sum + p.qty, 0),
  fastener: parts.value.filter((p) => p.kind === 'fastener').reduce((sum, p) => sum + p.qty, 0),
}));

onMounted(async () => {
  try {
    const response = await fetch(withBase(dataUrl('/catalog/parts.json', locale.value)));
    parts.value = (await response.json()).parts;
  } catch (cause) {
    error.value = cause instanceof Error ? cause.message : String(cause);
  }
});

function size(part: Part): string {
  return part.bbox_mm ? part.bbox_mm.map((v) => Math.round(v)).join(' × ') + ' mm' : '';
}
</script>

<template>
  <section class="yx-catalog">
    <p v-if="error" class="yx-catalog__error">{{ t.loadError(error) }} <a href="/catalog/strido-catalog.pdf">{{ t.pdf }}</a> {{ t.samePdf }}</p>
    <div class="yx-catalog__toolbar">
      <button v-for="option in (['all', 'printed', 'purchased', 'fastener'] as const)" :key="option" type="button"
              :class="{ active: kind === option }" @click="kind = option">
        {{ option === 'all' ? t.all : `${t[option]} (${totals[option]})` }}
      </button>
      <input v-model="query" type="search" :placeholder="t.filter" :aria-label="t.filterLabel" />
    </div>
    <div class="yx-catalog__grid">
      <article v-for="part in shown" :key="part.id" class="yx-part" :data-kind="part.kind">
        <img v-if="part.image" :src="withBase(part.image)" :alt="part.title" loading="lazy" />
        <div class="yx-part__body">
          <header><span class="yx-part__qty">{{ part.qty }}×</span> {{ part.title }}</header>
          <code>{{ part.id }}</code>
          <dl>
            <template v-if="size(part)"><dt>{{ t.size }}</dt><dd>{{ size(part) }}</dd></template>
            <template v-if="part.mass_g"><dt>{{ t.mass }}</dt><dd>{{ part.mass_g }} {{ t.each }}</dd></template>
            <template v-if="part.colour"><dt>{{ t.filament }}</dt><dd>{{ t.colour(part.colour) }}{{ part.supports ? t.supports : '' }}</dd></template>
            <template v-if="part.file"><dt>{{ t.file }}</dt><dd><a :href="`/print/stl/${part.file.split('/').pop()}`" download>{{ part.file.split('/').pop() }}</a></dd></template>
            <template v-if="part.vendor"><dt>{{ t.buy }}</dt><dd>{{ part.vendor }}<span v-if="part.sku"> · {{ part.sku }}</span><span v-if="part.price_eur"> · {{ formatMoney(part.price_eur, locale) }}<span v-if="part.pack && part.pack > 1"> / {{ part.pack }}</span></span></dd></template>
            <template v-if="part.steps?.length"><dt>{{ t.steps }}</dt><dd><template v-for="(step, index) in part.steps" :key="step">{{ index ? ', ' : '' }}<a :href="localePath(`/docs/assembly/#step-${step}`)">{{ step }}</a></template></dd></template>
          </dl>
          <p v-if="part.note" class="yx-part__note">{{ part.note }}</p>
        </div>
      </article>
    </div>
  </section>
</template>
